"""Evidence-reference guards and a disposable synthetic 12th-paper full import."""
import copy,hashlib,json,shutil,struct,subprocess,sys,tempfile,zlib
from pathlib import Path
from validate_publications import ROOT,validate
from promote_publication import promote

def read(p):return json.loads(p.read_text(encoding='utf-8'))
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def snapshot():return {p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in (ROOT/'data').glob('*.json')}
def main():
 before=snapshot();report={'negative':[]}
 with tempfile.TemporaryDirectory(prefix='qisun-v37-test-') as tmp:
  sandbox=Path(tmp)/'site';shutil.copytree(ROOT,sandbox,ignore=shutil.ignore_patterns('.git','node_modules','tmp','__pycache__','test-results'))
  cases=[('unsupported_excerpt','publication_details.json',lambda d:d[0]['focusBrief']['en']['problem'].update(text='UNSUPPORTED_SYNTHETIC_CLAIM')),
   ('wrong_natural_size','figures.json',lambda d:d[0]['naturalSize'].update(width=1)),
   ('wrong_figure_explanation','figures.json',lambda d:d[0]['explanation']['en']['information'].update(field='visuals.1.caption')),
   ('wrong_default_primary','research_visuals.json',lambda d:d['sections'][0]['previews'][0]['layout'].update(defaultPrimary='missing#figure')),
   ('invalid_media_weight','research_visuals.json',lambda d:d['sections'][0]['previews'][0]['layout'].update(primaryWeight=999))]
  for name,file,mutate in cases:
   target=sandbox/'data'/file;original=read(target);data=copy.deepcopy(original);mutate(data);write(target,data)
   errors=validate(sandbox)['errors'];assert errors,name;report['negative'].append({'name':name,'blocked':True,'errors':errors});write(target,original)
  slug='synthetic-test-only-v37';pub=copy.deepcopy(read(sandbox/'data/publications.json')[0])
  # Explicit test fixture, never promoted into the real checkout or output ZIP.
  pub.update(slug=slug,title='TEST ONLY: synthetic pipeline fixture; not a publication',citationKey=slug,doi='10.9999/test-only-v37',area='learning',selectedRank=None,figureCredit='Generated exclusively by the synthetic test; no scientific data.',links=[{'label':'TEST ONLY','url':'https://example.com/test-only-v37'}],metadataSources=['https://example.com/test-only-v37'])
  for key in ['publisher_citation_publication_date','date_provenance']:pub.pop(key,None)
  src='assets/images/paper-figures/'+slug+'-fixture.png'
  def chunk(kind,data):return struct.pack('>I',len(data))+kind+data+struct.pack('>I',zlib.crc32(kind+data)&0xffffffff)
  png=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',160,90,8,2,0,0,0))+chunk(b'IDAT',zlib.compress((b'\0'+b'\xe0\xee\xe8'*160)*90))+chunk(b'IEND',b'')
  (sandbox/src).write_bytes(png)
  visual={'src':src,'title':'TEST ONLY generated color tile','caption':'No scientific data; generated by this test.','insight':'Checks source-to-output wiring only.'}
  text={k:'TEST ONLY: no research claim.' for k in ['oneLine','coreClaim','problem','method','whyItMatters','discussion']}
  text.update(evidence=[],pipeline=[],highlights=[],visuals=[visual])
  detail={'slug':slug,**text,'en':copy.deepcopy(text)}
  figure={'id':slug+'#fixture','publication_slug':slug,'visual_index':0,'role':'framework','sourceUrl':'https://example.com/test-only-v37','rights':{'status':'verified','evidence':['Generated exclusively by this test; no third-party content.']},'naturalSize':{'width':160,'height':90},'readability':'wide'}
  draft={'publication':pub,'detail':detail,'figures':[figure],'features':{'selectedRank':None,'researchArea':'learning','figureRefs':[figure['id']]},'review':{'state':'publishable','metadata_verified':True,'content_reviewed':True,'rights_reviewed':True,'publishable':True,'author_order':pub['authors'],'evidence':['TEST ONLY simulated review stages; not a real publication or author claim.']}}
  draft_path=Path(tmp)/'draft.json';write(draft_path,draft);promote(draft_path,sandbox)
  built=subprocess.run([sys.executable,'-B','scripts/build_site.py'],cwd=sandbox,capture_output=True,text=True);assert built.returncode==0,built.stdout+built.stderr
  assert len(read(sandbox/'data/publications.json'))==12
  outputs=['research.html','en/research.html','publications.html','en/publications.html','papers/'+slug+'.html','en/papers/'+slug+'.html','assets/citations/'+slug+'.bib','sitemap.xml']
  for name in outputs:assert slug in (sandbox/name).read_text(encoding='utf-8'),name
  report['synthetic_full_pipeline']={'passed':True,'count_in_temporary_site':12,'generated_outputs':outputs,'research_card_and_figure':True,'temporary_fixture_only':True,'science_or_permission_not_inferred':True}
 assert snapshot()==before
 assert len(read(ROOT/'data/publications.json'))==11
 report['real_data_unchanged']=True
 out=ROOT/'tmp/v37/logs/contract_tests.json';out.parent.mkdir(parents=True,exist_ok=True);write(out,report)
 print(json.dumps({'new_negative_tests':len(report['negative']),'synthetic_full_pipeline':True,'production_records':11,'real_data_unchanged':True}))
if __name__=='__main__':main()
